    n = 87
    M = 171
    min_size = float('inf')

    # Try S = {0, 1, ..., k} \cup {M-j, ..., M}
    # such that |S| = n
    for k in range(100):
        for j in range(100):
            S = sorted(list(set(list(range(k + 1)) + list(range(M - j, M + 1)))))
            if len(S) == n:
